class Solution {
public:
    int dominantIndices(vector<int>& nums) {
        long long suffix = 0;
        int ans = 0;
        for (int i = (int)nums.size() - 1; i >= 0; --i) {
            int count = (int)nums.size() - 1 - i;
            if (count && (long long)nums[i] * count > suffix) ++ans;
            suffix += nums[i];
        }
        return ans;
    }
};
